-- Migration 0001: initial application schema.
--
-- Applied migrations are never edited; schema changes go in a new numbered
-- file. Timestamps are INTEGER Unix epoch milliseconds (UTC). Identifiers are
-- prefixed random strings generated by the Worker (never sequential).
--
-- The schema enforces invariants itself (CHECK constraints, foreign keys, and
-- triggers) as a second layer behind the repository code: invalid status
-- transitions, a decreasing revocation_version, ownership changes, and audit
-- rewrites are rejected even if application code is wrong.

-- ---------------------------------------------------------------------------
-- user_profiles: one application profile per authenticated identity.
-- auth_user_id is the auth system's opaque user id (Better Auth, Phase 4).
-- ---------------------------------------------------------------------------
CREATE TABLE user_profiles (
  id            TEXT    NOT NULL PRIMARY KEY CHECK (id GLOB 'usr_[a-z0-9]*' AND length(id) BETWEEN 12 AND 64),
  auth_user_id  TEXT    NOT NULL UNIQUE CHECK (length(auth_user_id) BETWEEN 1 AND 255),
  display_name  TEXT             CHECK (display_name IS NULL OR length(display_name) BETWEEN 1 AND 80),
  status        TEXT    NOT NULL DEFAULT 'pending'
                        CHECK (status IN ('pending', 'active', 'suspended', 'disabled')),
  created_at    INTEGER NOT NULL CHECK (created_at > 0),
  updated_at    INTEGER NOT NULL CHECK (updated_at >= created_at)
) STRICT;

CREATE TRIGGER user_profiles_immutable_id
BEFORE UPDATE OF id, auth_user_id ON user_profiles
WHEN NEW.id IS NOT OLD.id OR NEW.auth_user_id IS NOT OLD.auth_user_id
BEGIN
  SELECT RAISE(ABORT, 'immutable_column');
END;

CREATE TRIGGER user_profiles_status_transition
BEFORE UPDATE OF status ON user_profiles
WHEN NEW.status IS NOT OLD.status AND NOT (
     (OLD.status = 'pending'   AND NEW.status IN ('active', 'disabled'))
  OR (OLD.status = 'active'    AND NEW.status IN ('suspended', 'disabled'))
  OR (OLD.status = 'suspended' AND NEW.status IN ('active', 'disabled'))
)
BEGIN
  SELECT RAISE(ABORT, 'invalid_status_transition');
END;

-- ---------------------------------------------------------------------------
-- harnesses: Lightagent installations. Administrator-controlled only.
-- No private keys or overlay-network credentials are stored here.
-- ---------------------------------------------------------------------------
CREATE TABLE harnesses (
  id                TEXT    NOT NULL PRIMARY KEY CHECK (id GLOB 'hns_[a-z0-9]*' AND length(id) BETWEEN 12 AND 64),
  name              TEXT    NOT NULL UNIQUE CHECK (length(name) BETWEEN 1 AND 80),
  environment       TEXT    NOT NULL CHECK (environment IN ('development', 'staging', 'production')),
  -- Base URL of the harness control gateway. https only, except http in development.
  endpoint          TEXT    NOT NULL CHECK (
                      length(endpoint) BETWEEN 10 AND 2048
                      AND (endpoint GLOB 'https://*' OR (environment = 'development' AND endpoint GLOB 'http://*'))
                    ),
  -- Id of the control-plane signing key this harness trusts (selects which
  -- Worker key signs its commands). Not secret.
  key_id            TEXT    NOT NULL CHECK (length(key_id) BETWEEN 1 AND 64 AND key_id NOT GLOB '*[^A-Za-z0-9._-]*'),
  -- The harness's own Ed25519 public key (base64, 32 bytes), reserved for
  -- verifying signed harness responses. NULL until that protocol is defined.
  public_key        TEXT             CHECK (public_key IS NULL OR length(public_key) = 44),
  status            TEXT    NOT NULL DEFAULT 'disabled' CHECK (status IN ('active', 'draining', 'disabled')),
  capabilities_json TEXT    NOT NULL DEFAULT '{}' CHECK (json_valid(capabilities_json) AND length(capabilities_json) <= 2048),
  created_at        INTEGER NOT NULL CHECK (created_at > 0),
  updated_at        INTEGER NOT NULL CHECK (updated_at >= created_at),
  last_seen_at      INTEGER
) STRICT;

CREATE TRIGGER harnesses_immutable_id
BEFORE UPDATE OF id, environment ON harnesses
WHEN NEW.id IS NOT OLD.id OR NEW.environment IS NOT OLD.environment
BEGIN
  SELECT RAISE(ABORT, 'immutable_column');
END;

-- ---------------------------------------------------------------------------
-- agent_profiles: a user's Lightagent agents. user_id is the canonical owner.
-- revocation_version starts at 1 and only ever increases; signed commands
-- carry it so harnesses reject commands issued before a revocation.
-- ---------------------------------------------------------------------------
CREATE TABLE agent_profiles (
  id                 TEXT    NOT NULL PRIMARY KEY CHECK (id GLOB 'agt_[a-z0-9]*' AND length(id) BETWEEN 12 AND 64),
  user_id            TEXT    NOT NULL REFERENCES user_profiles (id) ON DELETE RESTRICT,
  agent_name         TEXT    NOT NULL CHECK (length(agent_name) BETWEEN 1 AND 80),
  status             TEXT    NOT NULL DEFAULT 'pending'
                             CHECK (status IN ('pending', 'provisioning', 'active', 'failed', 'suspended', 'revoked')),
  harness_id         TEXT             REFERENCES harnesses (id) ON DELETE RESTRICT,
  revocation_version INTEGER NOT NULL DEFAULT 1 CHECK (revocation_version >= 1),
  -- Server-chosen permission ceiling (validated JSON, see db/json.ts).
  permissions_json   TEXT    NOT NULL CHECK (json_valid(permissions_json) AND length(permissions_json) <= 512),
  created_at         INTEGER NOT NULL CHECK (created_at > 0),
  updated_at         INTEGER NOT NULL CHECK (updated_at >= created_at),
  last_seen_at       INTEGER,
  -- A profile that is provisioning or live must be placed on a harness.
  CHECK (status NOT IN ('provisioning', 'active', 'suspended') OR harness_id IS NOT NULL)
) STRICT;

CREATE INDEX agent_profiles_by_user ON agent_profiles (user_id, created_at);
CREATE INDEX agent_profiles_by_harness ON agent_profiles (harness_id) WHERE harness_id IS NOT NULL;

CREATE TRIGGER agent_profiles_immutable_owner
BEFORE UPDATE OF id, user_id ON agent_profiles
WHEN NEW.id IS NOT OLD.id OR NEW.user_id IS NOT OLD.user_id
BEGIN
  SELECT RAISE(ABORT, 'immutable_column');
END;

CREATE TRIGGER agent_profiles_revocation_monotonic
BEFORE UPDATE OF revocation_version ON agent_profiles
WHEN NEW.revocation_version < OLD.revocation_version
BEGIN
  SELECT RAISE(ABORT, 'revocation_version_decrease');
END;

CREATE TRIGGER agent_profiles_status_transition
BEFORE UPDATE OF status ON agent_profiles
WHEN NEW.status IS NOT OLD.status AND NOT (
     (OLD.status = 'pending'      AND NEW.status IN ('provisioning', 'revoked'))
  OR (OLD.status = 'provisioning' AND NEW.status IN ('active', 'failed'))
  OR (OLD.status = 'failed'       AND NEW.status IN ('provisioning', 'revoked'))
  OR (OLD.status = 'active'       AND NEW.status IN ('suspended', 'revoked'))
  OR (OLD.status = 'suspended'    AND NEW.status IN ('active', 'revoked'))
)
BEGIN
  SELECT RAISE(ABORT, 'invalid_status_transition');
END;

-- ---------------------------------------------------------------------------
-- provisioning_jobs: one signed control command and its delivery state.
-- idempotency_key is globally unique; request_hash pins the payload so a
-- reused key with a different payload is a conflict, never a second job.
-- ---------------------------------------------------------------------------
CREATE TABLE provisioning_jobs (
  id               TEXT    NOT NULL PRIMARY KEY CHECK (id GLOB 'prv_[a-z0-9]*' AND length(id) BETWEEN 12 AND 64),
  user_id          TEXT    NOT NULL REFERENCES user_profiles (id) ON DELETE RESTRICT,
  agent_profile_id TEXT    NOT NULL REFERENCES agent_profiles (id) ON DELETE RESTRICT,
  harness_id       TEXT    NOT NULL REFERENCES harnesses (id) ON DELETE RESTRICT,
  operation        TEXT    NOT NULL CHECK (operation IN ('profile.create', 'profile.disable', 'profile.enable', 'profile.revoke')),
  request_id       TEXT    NOT NULL CHECK (request_id GLOB 'req_[a-z0-9]*' AND length(request_id) BETWEEN 12 AND 64),
  idempotency_key  TEXT    NOT NULL UNIQUE CHECK (length(idempotency_key) BETWEEN 16 AND 128 AND idempotency_key NOT GLOB '*[^A-Za-z0-9_-]*'),
  -- Lowercase hex SHA-256 of the canonical command payload.
  request_hash     TEXT    NOT NULL CHECK (length(request_hash) = 64 AND request_hash NOT GLOB '*[^0-9a-f]*'),
  status           TEXT    NOT NULL DEFAULT 'pending'
                           CHECK (status IN ('pending', 'sending', 'accepted', 'completed', 'failed', 'cancelled')),
  attempt_count    INTEGER NOT NULL DEFAULT 0 CHECK (attempt_count BETWEEN 0 AND 10),
  error_code       TEXT             CHECK (error_code IS NULL OR (length(error_code) BETWEEN 1 AND 64 AND error_code NOT GLOB '*[^A-Z0-9_]*')),
  created_at       INTEGER NOT NULL CHECK (created_at > 0),
  updated_at       INTEGER NOT NULL CHECK (updated_at >= created_at),
  completed_at     INTEGER,
  -- Terminal states and completed_at go together; failures carry a code.
  CHECK ((status IN ('completed', 'failed', 'cancelled')) = (completed_at IS NOT NULL)),
  CHECK (status <> 'failed' OR error_code IS NOT NULL)
) STRICT;

-- At most one in-flight job per profile and operation.
CREATE UNIQUE INDEX provisioning_jobs_one_in_flight
  ON provisioning_jobs (agent_profile_id, operation)
  WHERE status IN ('pending', 'sending', 'accepted');
CREATE INDEX provisioning_jobs_by_user ON provisioning_jobs (user_id, created_at);
CREATE INDEX provisioning_jobs_by_profile ON provisioning_jobs (agent_profile_id, created_at);

CREATE TRIGGER provisioning_jobs_immutable
BEFORE UPDATE OF id, user_id, agent_profile_id, harness_id, operation, request_id, idempotency_key, request_hash
ON provisioning_jobs
WHEN NEW.id IS NOT OLD.id OR NEW.user_id IS NOT OLD.user_id OR NEW.agent_profile_id IS NOT OLD.agent_profile_id
  OR NEW.harness_id IS NOT OLD.harness_id OR NEW.operation IS NOT OLD.operation OR NEW.request_id IS NOT OLD.request_id
  OR NEW.idempotency_key IS NOT OLD.idempotency_key OR NEW.request_hash IS NOT OLD.request_hash
BEGIN
  SELECT RAISE(ABORT, 'immutable_column');
END;

CREATE TRIGGER provisioning_jobs_status_transition
BEFORE UPDATE OF status ON provisioning_jobs
WHEN NEW.status IS NOT OLD.status AND NOT (
     (OLD.status = 'pending'  AND NEW.status IN ('sending', 'cancelled', 'failed'))
  OR (OLD.status = 'sending'  AND NEW.status IN ('pending', 'accepted', 'completed', 'failed'))
  OR (OLD.status = 'accepted' AND NEW.status IN ('completed', 'failed'))
)
BEGIN
  SELECT RAISE(ABORT, 'invalid_status_transition');
END;

-- ---------------------------------------------------------------------------
-- provisioning_nonces: hashes of nonces the Worker has issued, so a nonce is
-- never reused. Only SHA-256 hashes are stored. Rows are deletable once
-- expired (see docs/DATABASE.md, retention).
-- ---------------------------------------------------------------------------
CREATE TABLE provisioning_nonces (
  nonce_hash TEXT    NOT NULL PRIMARY KEY CHECK (length(nonce_hash) = 64 AND nonce_hash NOT GLOB '*[^0-9a-f]*'),
  created_at INTEGER NOT NULL CHECK (created_at > 0),
  expires_at INTEGER NOT NULL CHECK (expires_at > created_at)
) STRICT;

CREATE INDEX provisioning_nonces_by_expiry ON provisioning_nonces (expires_at);

-- ---------------------------------------------------------------------------
-- audit_events: append-only security log. Rows are validated by
-- createAuditEvent before insert. security_metadata_json holds a keyed hash
-- of the source address, never the raw IP.
-- ---------------------------------------------------------------------------
CREATE TABLE audit_events (
  id                     TEXT    NOT NULL PRIMARY KEY CHECK (id GLOB 'aud_[a-z0-9]*' AND length(id) BETWEEN 12 AND 64),
  timestamp              INTEGER NOT NULL CHECK (timestamp > 0),
  actor_type             TEXT    NOT NULL CHECK (actor_type IN ('user', 'admin', 'system', 'anonymous')),
  actor_id               TEXT             CHECK (actor_id IS NULL OR length(actor_id) BETWEEN 1 AND 64),
  action                 TEXT    NOT NULL CHECK (length(action) BETWEEN 1 AND 64),
  target_type            TEXT             CHECK (target_type IS NULL OR length(target_type) BETWEEN 1 AND 32),
  target_id              TEXT             CHECK (target_id IS NULL OR length(target_id) BETWEEN 1 AND 64),
  request_id             TEXT    NOT NULL CHECK (length(request_id) BETWEEN 1 AND 64),
  result                 TEXT    NOT NULL CHECK (result IN ('success', 'failure', 'denied')),
  reason                 TEXT             CHECK (reason IS NULL OR (length(reason) BETWEEN 1 AND 64 AND reason NOT GLOB '*[^A-Z0-9_]*')),
  security_metadata_json TEXT    NOT NULL DEFAULT '{}' CHECK (json_valid(security_metadata_json) AND length(security_metadata_json) <= 512),
  details_json           TEXT    NOT NULL DEFAULT '{}' CHECK (json_valid(details_json) AND length(details_json) <= 4096),
  CHECK ((actor_type = 'anonymous') = (actor_id IS NULL)),
  CHECK ((target_type IS NULL) = (target_id IS NULL))
) STRICT;

CREATE INDEX audit_events_by_time ON audit_events (timestamp);
CREATE INDEX audit_events_by_actor ON audit_events (actor_type, actor_id, timestamp) WHERE actor_id IS NOT NULL;
CREATE INDEX audit_events_by_target ON audit_events (target_type, target_id, timestamp) WHERE target_id IS NOT NULL;
CREATE INDEX audit_events_by_request ON audit_events (request_id);
CREATE INDEX audit_events_by_source ON audit_events (json_extract(security_metadata_json, '$.sourceHash'))
  WHERE json_extract(security_metadata_json, '$.sourceHash') IS NOT NULL;

CREATE TRIGGER audit_events_append_only
BEFORE UPDATE ON audit_events
BEGIN
  SELECT RAISE(ABORT, 'audit_events_append_only');
END;
